template <typename T>
int linearSearch(const std::vector<T>& values, const T& target) {
    const int size = static_cast<int>(values.size());
    for (int i = 0; i < size; i++) {
        if (values[i] == target) {
            return i;
        }
    }
    return -1;
}

template <typename T>
int binarySearch(const std::vector<T>& values, const T& target) {
    int low = 0;
    int high = static_cast<int>(values.size()) - 1;
    while (low <= high) {
        const int mid = low + (high - low) / 2;
        if (values[mid] == target) {
            return mid;
        }
        if (values[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return -1;
}

template <typename T>
void bubbleSort(std::vector<T>& values) {
    const int size = static_cast<int>(values.size());
    for (int pass = 0; pass < size - 1; pass++) {
        for (int i = 0; i < size - 1 - pass; i++) {
            if (values[i] > values[i + 1]) {
                std::swap(values[i], values[i + 1]);
            }
        }
    }
}

template <typename T>
void selectionSort(std::vector<T>& values) {
    const int size = static_cast<int>(values.size());
    for (int i = 0; i < size - 1; i++) {
        int minIndex = i;
        for (int j = i + 1; j < size; j++) {
            if (values[j] < values[minIndex]) {
                minIndex = j;
            }
        }
        std::swap(values[i], values[minIndex]);
    }
}

template <typename T>
void insertionSort(std::vector<T>& values) {
    const int size = static_cast<int>(values.size());
    for (int i = 1; i < size; i++) {
        const T key = values[i];
        int j = i - 1;
        while (j >= 0 && values[j] > key) {
            values[j + 1] = values[j];
            j--;
        }
        values[j + 1] = key;
    }
}

template <typename T>
void merge(std::vector<T>& values, int left, int mid, int right) {
    std::vector<T> leftHalf(values.begin() + left, values.begin() + mid + 1);
    std::vector<T> rightHalf(values.begin() + mid + 1,
                             values.begin() + right + 1);
    int i = 0;
    int j = 0;
    int k = left;
    while (i < static_cast<int>(leftHalf.size()) &&
           j < static_cast<int>(rightHalf.size())) {
        if (leftHalf[i] <= rightHalf[j]) {
            values[k++] = leftHalf[i++];
        } else {
            values[k++] = rightHalf[j++];
        }
    }
    while (i < static_cast<int>(leftHalf.size())) {
        values[k++] = leftHalf[i++];
    }
    while (j < static_cast<int>(rightHalf.size())) {
        values[k++] = rightHalf[j++];
    }
}

template <typename T>
void mergeSort(std::vector<T>& values, int left, int right) {
    if (left >= right) {
        return;
    }
    const int mid = left + (right - left) / 2;
    mergeSort(values, left, mid);
    mergeSort(values, mid + 1, right);
    merge(values, left, mid, right);
}

template <typename T>
int partition(std::vector<T>& values, int low, int high) {
    const T pivot = values[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (values[j] <= pivot) {
            i++;
            std::swap(values[i], values[j]);
        }
    }
    std::swap(values[i + 1], values[high]);
    return i + 1;
}

template <typename T>
void quickSort(std::vector<T>& values, int low, int high) {
    if (low >= high) {
        return;
    }
    const int pivotIndex = partition(values, low, high);
    quickSort(values, low, pivotIndex - 1);
    quickSort(values, pivotIndex + 1, high);
}

template <typename T>
void siftDown(std::vector<T>& values, int size, int root) {
    while (true) {
        int largest = root;
        const int left = 2 * root + 1;
        const int right = 2 * root + 2;
        if (left < size && values[left] > values[largest]) {
            largest = left;
        }
        if (right < size && values[right] > values[largest]) {
            largest = right;
        }
        if (largest == root) {
            return;
        }
        std::swap(values[root], values[largest]);
        root = largest;
    }
}

template <typename T>
void heapSort(std::vector<T>& values) {
    const int size = static_cast<int>(values.size());
    for (int i = size / 2 - 1; i >= 0; i--) {
        siftDown(values, size, i);
    }
    for (int end = size - 1; end > 0; end--) {
        std::swap(values[0], values[end]);
        siftDown(values, end, 0);
    }
}

class Graph {
public:
    explicit Graph(int nodes) : adjacency_(nodes) {}

    void addEdge(int from, int to) {
        adjacency_[from].push_back(to);
        adjacency_[to].push_back(from);
    }

    const std::vector<int>& neighbors(int node) const {
        return adjacency_[node];
    }

    int size() const { return static_cast<int>(adjacency_.size()); }

private:
    std::vector<std::vector<int>> adjacency_;
};

std::vector<int> bfs(const Graph& graph, int start) {
    std::vector<bool> visited(graph.size(), false);
    std::vector<int> order;
    std::queue<int> pending;
    visited[start] = true;
    pending.push(start);
    while (!pending.empty()) {
        const int node = pending.front();
        pending.pop();
        order.push_back(node);
        for (int next : graph.neighbors(node)) {
            if (!visited[next]) {
                visited[next] = true;
                pending.push(next);
            }
        }
    }
    return order;
}

void visit(const Graph& graph, int node, std::vector<bool>& visited,
           std::vector<int>& order) {
    visited[node] = true;
    order.push_back(node);
    for (int next : graph.neighbors(node)) {
        if (!visited[next]) {
            visit(graph, next, visited, order);
        }
    }
}

std::vector<int> dfs(const Graph& graph, int start) {
    std::vector<bool> visited(graph.size(), false);
    std::vector<int> order;
    visit(graph, start, visited, order);
    return order;
}

struct Edge {
    int to;
    int weight;
};

class WeightedGraph {
public:
    explicit WeightedGraph(int nodes) : adjacency_(nodes) {}

    void addEdge(int from, int to, int weight) {
        adjacency_[from].push_back({to, weight});
        adjacency_[to].push_back({from, weight});
    }

    const std::vector<Edge>& neighbors(int node) const {
        return adjacency_[node];
    }

    int size() const { return static_cast<int>(adjacency_.size()); }

private:
    std::vector<std::vector<Edge>> adjacency_;
};

std::vector<int> dijkstra(const WeightedGraph& graph, int start) {
    const int unreachable = -1;
    std::vector<int> distances(graph.size(), unreachable);
    std::vector<bool> visited(graph.size(), false);
    distances[start] = 0;
    for (int step = 0; step < graph.size(); step++) {
        int current = -1;
        for (int node = 0; node < graph.size(); node++) {
            if (!visited[node] && distances[node] != unreachable &&
                (current == -1 || distances[node] < distances[current])) {
                current = node;
            }
        }
        if (current == -1) {
            break;
        }
        visited[current] = true;
        for (const Edge& edge : graph.neighbors(current)) {
            const int candidate = distances[current] + edge.weight;
            if (distances[edge.to] == unreachable ||
                candidate < distances[edge.to]) {
                distances[edge.to] = candidate;
            }
        }
    }
    return distances;
}

